@warp E -> ruta_4 spawn=east
@warp n -> ruta_24 spawn=south
@warp g -> gimnasio_marea spawn=door
@warp z -> centro_marea spawn=door
@warp T -> tienda_marea spawn=door
@warp y -> ruta_5 spawn=north
@warp e -> ruta_9 spawn=west
@warp D -> cueva_secreta_1 spawn=south
@warp j -> tienda_bicis spawn=door
@warp J -> almacen_asaltado spawn=door
# The rival: when the player steps in front of the north gate the first time he appears on the arch, talks, fights (trainer rival_marea: the stage-2 counter of the
# starter + Flitwing 18, Dozelf 15, Muncrit 15) and leaves for Ingeniero Teo's. A lost fight is the normal blackout; he then stays on the arch and talking to him fights again.
@script rival_ambush step if !rival2_gone
    setf rival2_here
    cam_npc rival
    wait 400
    npc_face_hero rival
    say marea.rival.hey
    cam_hero
    call rival_fight
@end
@script rival_talk npc
    npc_face_hero rival
    say marea.rival.again
    call rival_fight
@end
@script rival_fight called
    battle 20 0
    jv 0 1 won
    blackout
    end
  won:
    say marea.rival.lose
    say marea.rival.next
    setf rival2_gone
@end
# The harbour guard (C9): the hatch behind him leads to the Cueva Secreta, which only the champion may enter (he hides once flag league_champion is set: the Hall of Legacy was entered).
@script cave_guard npc
    npc_face_hero cave_guard
    say marea.cave.guard
    npc_face cave_guard SE
@end
